# ───────────────────────── القبول والقرعة ─────────────────────────
CHAPTERS.append({
    "title": "القبول المباشر والقرعة",
    "intro": "القبول المباشر والقرعة تسجيلان منفصلان، لكلٍّ منهما طلب مستقل. صفحة «القبول والقرعة» أربع خطوات بالترتيب، لكل خطوة شاشتها: الأعمار المقبولة مباشرة، إحصاء التسجيل الأولي على القرعة، إدخال نتائج البث، الاعتماد والنشر. القرعة نفسها تجري خارج المنصة ببث مباشر تُسحب فيه سنوات ميلاد، ولبعضها أشهر محددة، ويُقبل كل طلب وُلد صاحبه في سنة وشهر مسحوبين. لكل خطوة صلاحيتها: «إرسال الأعمار للاعتماد» و«اعتماد الأعمار وإعلانها»، و«تصدير الإحصاء»، و«إضافة — نتائج البث» و«تعديل» و«إرسال النتائج للاعتماد»، و«اعتماد النتائج ونشرها». والإدخال مفصول عن الاعتماد عمداً حتى لا ينفرد شخص واحد بالنتيجة: إدارة التسجيل (كنان الأحمد) ترسل الأعمار وتصدّر الإحصاء وتُدخل ما سُحب، ولجنة الاعتماد (يوسف الزعبي) تعتمد وتنشر. ومن أدخل النتائج لا يعتمدها ولو مُنح الصلاحيتين معاً. وأرقام القبول والقرعة في «الإحصائيات» تحت اسم النظام في القائمة، وهي صلاحية وحدها مُنحت لكنان ويوسف كليهما.",
    "sections": [
        {"title": "عمل إدارة التسجيل (الإدخال)", "steps": [
            S("القبول المباشر والقرعة", "جدول الخطوات الأربع: لكل خطوة حالتها، و«آخر إجراء» (من قام به ومتى)، و«من يقوم بها»، وتحت اسمها ما ينتظرك فيها أو «فتح». وفي آخر الصفحة «كيف تعمل؟». في بيئة العرض تُفتح الصفحة على نتائج موسم 1448 منشورةً («بث 1448»)، وزر «إعادة التجربة» في الأعلى يعيد الخطوات من البداية.", "lot-list",
              do=["في النسخة التجريبية: اضغط «إعادة التجربة» (الإطار 1)."], r="تظهر «أُعيدت خطوات القرعة»، وتُسحب النتائج المنشورة من العرض حتى تُنشر من جديد."),
            S("الخطوات من البداية", "تصير الحالات «لم تبدأ» و«لم يُصدَّر» و«لم تُدخل» و«بانتظار الإدخال»، وتحت كل خطوة ما تفعله فيها: «إرسال للاعتماد»، «تصدير»، «إدخال النتائج».", "lot-reset",
              do=["اضغط «إرسال للاعتماد» تحت الخطوة الأولى (الإطار 1)."], r="تُفتح شاشة الأعمار المقبولة."),
            S("الأعمار المقبولة", "في الوسط العمر الذي تكتمل عنده مقاعد القبول المباشر («كل من بلغ 68 عاماً فأكثر — مقبول مباشرة») وموعد إعلانه، ثم جدول الطلبات المؤهلة مرتبة من الأكبر سناً: العمر، والمقاعد، والمجموع حتى هنا، و«مقبول مباشرة» أو «إلى القرعة». وفي الجانب صندوق «الإعلان» بخطوتيه.", "lot-ages",
              do=["راجع القائمة، ثم اضغط «إرسال للاعتماد» (الإطار 1)."], r="—"),
            S("أُرسلت الأعمار للاعتماد", "تظهر «أُرسلت الأعمار المقبولة للاعتماد»، وتُعلَّم الخطوة الأولى في الصندوق باسمك ووقتك، وتحتها أن الاعتماد من صلاحية «اعتماد الأعمار وإعلانها».", "lot-sent",
              do=["ارجع إلى «كل الخطوات» وافتح الخطوة الثانية."], r="—"),
            S("إحصاء التسجيل الأولي على القرعة", "بعد إغلاق التسجيل الأولي تُحصي المنصة المسجّلين بسنة ميلاد صاحب الطلب: لكل سنة عدد الأشخاص وعدد الطلبات، وتحت كل سنة «الأشهر» (الإطار 1). وفي الجانب صندوق «التصدير» وزر «تصدير الإحصاء للجنة تنظيم القرعة» (الإطار 2).", "lot-pool",
              do=["اضغط «الأشهر» تحت سنة لترى توزيعها على الأشهر."], r="—"),
            S("أشهر سنة واحدة", "يظهر عدد المسجّلين في كل شهر من السنة، فتعرف اللجنة كم مقعداً يشغل كل شهر، وتتوقف عن السحب حين تكتمل المقاعد. و«إخفاء الأشهر» (الإطار 1) يطويها.", "lot-pool-months",
              do=["بعد المراجعة اضغط «تصدير الإحصاء للجنة تنظيم القرعة» في أعلى الشاشة."], r="—"),
            S("تصدير الإحصاء", "يُعدّ الملف الذي يُسلَّم إلى لجنة تنظيم القرعة قبل البث، وتظهر «صُدّر إحصاء التسجيل الأولي» باسم الملف، ويصير في الصندوق «صُدّر بواسطة …» مع الوقت.", "lot-export",
              do=["سلّم الملف إلى اللجنة."], r="يُسجَّل التصدير باسمك ووقته."),
            S("إدخال ما سُحب في البث", "شاشة «إدخال نتائج البث»: في الجانب صندوق «إضافة سطر»: «سنة الميلاد» (مع عدد من فيها)، ثم «جميع الأشهر» أو «أشهر محددة» مع أزرار الأشهر الاثني عشر. وفي الوسط السطور المُدخلة (السنة، وما سُحب، والأشخاص) مع زر حذف لكل سطر، وتحتها شريط المقاعد المغطاة من مقاعد القرعة.", "lot-entry",
              do=["اختر سنة الميلاد.", "اختر «جميع الأشهر»، أو «أشهر محددة» ثم اضغط كل شهر سُحب.", "اضغط «إضافة السطر» (الإطار 1)."], r="يظهر السطر مع عدد من يشملهم، ويتقدم الشريط."),
            S("اكتمال مقاعد القرعة", "يقيس الشريط ما أُدخل بمقاعد القرعة: «بقي … مقعداً» حتى «اكتملت مقاعد القرعة»، و«تزيد … مقعداً — راجع ما أُدخل» إن تجاوزها. في بيئة العرض يعبّئ رابط «في بيئة العرض: تعبئة ما أُعلن في بث 1448» السطور كلها مكان ما أُدخل.", "lot-entered",
              do=["قارن السطور بما أُعلن في البث.", "اضغط «حفظ وإرسال للاعتماد» (الإطار 1)."], r="تظهر «أُرسلت نتائج القرعة للاعتماد». لا يرى الحجاج شيئاً قبل الاعتماد والنشر."),
            S("أُرسلت النتائج", "تظهر السطور للقراءة فقط، وفي صندوق «الحالة» «أُرسلت للاعتماد» باسمك ووقتك، وزر «تعديل قبل الاعتماد» (الإطار 1).", "lot-entry-sent",
              do=["إن وجدت خطأً قبل الاعتماد: اضغط «تعديل قبل الاعتماد» وصحّح ثم أرسل من جديد."], r="—"),
            S("النشر يحتاج صلاحية أخرى", "في شاشة «اعتماد ونشر نتائج القرعة» يرى صاحب الإدخال «وصلت للاعتماد: … — أدخلها …»، وزر «اعتماد ونشر النتائج» غير مفعّل، وتحته «يتطلب صلاحية «اعتماد النتائج ونشرها»، ولا يعتمدها من أدخلها. فصل الإدخال عن الاعتماد يمنع أن ينفرد شخص واحد بالنتيجة.».", "lot-locked-publish",
              do=["أبلغ صاحب صلاحية الاعتماد."], r="—"),
        ]},
        {"title": "عمل لجنة الاعتماد (الاعتماد والنشر)", "steps": [
            S("ما ينتظر الاعتماد", "قائمة الخطوات كما تراها لجنة الاعتماد: الخطوة الأولى «بانتظار الاعتماد» وتحتها «اعتماد وإعلان» (الإطار 1)، والرابعة «بانتظار الاعتماد» وتحتها «اعتماد ونشر» (الإطار 2)، ومع كل خطوة من أرسلها ومتى.", "lot-yousef",
              do=["اضغط «اعتماد وإعلان» تحت الخطوة الأولى."], r="تُفتح شاشة الأعمار المقبولة."),
            S("اعتماد وإعلان الأعمار", "الشاشة نفسها، وفي صندوق «الإعلان» زر «اعتماد وإعلان الأعمار» (يُفعَّل بعد إرسال إدارة التسجيل). الاعتماد يحدّث «الأعمار المقبولة مباشرة» في إعدادات الموسم إن اختلفت.", "lot-approve-ages",
              do=["اضغط «اعتماد وإعلان الأعمار» (الإطار 1)."], r="تظهر «أُعلنت الأعمار المقبولة»، ويصل إشعار لكل مقبول مباشرة."),
            S("اعتماد ونشر النتائج", "في شاشة «اعتماد ونشر نتائج القرعة»: «وصلت للاعتماد: … سنوات ميلاد، … مقعداً — أدخلها …»، والسطور كما أُرسلت مع شريط المقاعد، وزر «اعتماد ونشر النتائج» (الإطار 1).", "lot-publish",
              do=["راجع السطور مع ما أُعلن في البث، ثم اضغط «اعتماد ونشر النتائج»."], r="تظهر نافذة تأكيد."),
            S("تأكيد النشر", "نافذة «اعتماد ونشر نتائج القرعة؟»: السنوات والأشهر، وعدد الطلبات والأشخاص الذين يُقبلون بها، ومن أدخلها ومتى، وأن القبول المباشر لا يتغير بهذا النشر، ثم «لا يمكن التراجع عن النشر. سيُسجَّل الاعتماد باسمك ووقته.».", "lot-publish-modal",
              do=["اضغط «اعتماد ونشر» (الإطار 1)، أو «إلغاء»."], r="—", warn="لا يمكن التراجع عن النشر: يعرف كل مسجّل نتيجته في حسابه، ويظهر جدول السنوات والأشهر على صفحة نتائج القبول."),
            S("نُشرت النتائج", "تظهر «نُشرت نتائج القرعة»، وفي الصندوق «اعتمدها ونشرها: …» مع الوقت، وعدد سنوات الميلاد والطلبات والأشخاص المقبولين.", "lot-published",
              do=["—"], r="يبدأ المقبولون تثبيت تسجيلهم في المدة المكتوبة أعلى الشاشة."),
        ]},
    ],
})
